type State struct{ Busy bool; Err string }
type Bloc struct {
    mu    sync.RWMutex
    state State
    subs  map[chan State]struct{}
}
func (b *Bloc) Dispatch(ev Event) {
    b.mu.Lock()
    b.state = reduce(b.state, ev)     // pure (State, Event) -> State
    subs := snapshot(b.subs); b.mu.Unlock()   // copy, never call out locked
    for _, ch := range subs { select { case ch <- b.state: default: } }
}
